static void rich_pl011_uart_set_mctrl(struct uart_port *port, unsigned int mctrl)
{
	struct rich_pl011_priv *priv = port->private_data;
	unsigned int driven = mctrl & (TIOCM_DTR | TIOCM_RTS);
	struct ModemSignalSet signals;
	struct SerialStatus status;

	/* serial-core may repeat the applied state during registration/resume. */
	if (driven == priv->__rseq_mctrl)
		return;
	signals = (struct ModemSignalSet){
		.dtr = !!(driven & TIOCM_DTR), .rts = !!(driven & TIOCM_RTS),
	};
	status = rich_pl011_serial_set_signals(&priv->inner, signals);
	if (status._raw[0] == 0)
		priv->__rseq_mctrl = driven;
}

static unsigned int rich_pl011_uart_get_mctrl(struct uart_port *port)
{
	struct rich_pl011_priv *priv = port->private_data;
	struct ModemSignalSet signals = rich_pl011_serial_get_signals(&priv->inner);
	unsigned int value = 0;

	if (signals.cts) value |= TIOCM_CTS;
	if (signals.dsr) value |= TIOCM_DSR;
	if (signals.dcd) value |= TIOCM_CAR;
	if (signals.ri) value |= TIOCM_RNG;
	return value;
}

