static int rich_pl011_uart_verify_port(struct uart_port *port, struct serial_struct *serial)
{
	if (serial->type != PORT_UNKNOWN && serial->type != PORT_AMBA)
		return -EINVAL;
	if (serial->irq < 0 || serial->irq >= irq_get_nr_irqs())
		return -EINVAL;
	if (serial->baud_base < 9600)
		return -EINVAL;
	if (port->mapbase != (unsigned long)serial->iomem_base)
		return -EINVAL;
	return 0;
}

