	priv->__rseq_uart_port.mapbase = adev->res.start;
	priv->__rseq_uart_port.membase = priv->inner.regs;
	priv->__rseq_uart_port.irq = adev->irq[0];
	priv->__rseq_uart_port.iotype = UPIO_MEM32;
	priv->__rseq_uart_port.type = PORT_AMBA;
	priv->__rseq_uart_port.fifosize = 16;
	priv->__rseq_uart_port.flags = UPF_BOOT_AUTOCONF | UPF_FIXED_PORT | UPF_FIXED_TYPE;
	priv->__rseq_uart_port.line = 0;
	priv->__rseq_uart_port.uartclk = 24000000;
	priv->__rseq_uart_port.private_data = priv;
	priv->__rseq_uart_port.ops = &rich_pl011_uart_ops;
