	ret = uart_add_one_port(&rich_pl011_uart_driver, &priv->__rseq_uart_port);
	if (ret) {
		(void)rich_pl011_on_deinit(&priv->inner);
		disable_irq(adev->irq[0]);
		free_irq(adev->irq[0], priv);
		return ret;
	}
